// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Uninterpreted component action abstractions, used ONLY by the
//! Commutativity VCs. Verus proves those VCs for ALL interpretations of
//! the action fns; the real component behaviors are one interpretation
//! (components only write their declared out ports/state, and outputs
//! depend only on the read scope), so a discharged Commutativity VC
//! establishes the Isabelle `execIndependent` obligation.

#![allow(non_snake_case)]
#![allow(unused_variables)]

use data::*;
use vstd::prelude::*;

use crate::system_state::SystemState;
use crate::write_frames::*;

verus! {

// -- Isolette_System_Instance.temp_sensor.temp_sensor --

pub uninterp spec fn sensor_action_current_temp(current_temp: Isolette_Data_Model::Temp, temp_changed: Option<u8>) -> Isolette_Data_Model::Temp;
pub uninterp spec fn sensor_action_temp_changed(current_temp: Isolette_Data_Model::Temp, temp_changed: Option<u8>) -> Option<u8>;

/** "SENSOR fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn sensor_fire(pre: SystemState, post: SystemState) -> bool
{
  post.sensedTemp == sensor_action_current_temp(pre.sensedTemp, pre.tempChanged)
  && post.tempChanged == sensor_action_temp_changed(pre.sensedTemp, pre.tempChanged)
  && sensor_global_write_frame(pre, post)
}

// -- Isolette_System_Instance.operator_interface.operator_interface --

pub uninterp spec fn oi_action_desired_temp(desired_temp: Option<Isolette_Data_Model::Set_Points>) -> Option<Isolette_Data_Model::Set_Points>;

/** "OI fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn oi_fire(pre: SystemState, post: SystemState) -> bool
{
  post.desired_temp == oi_action_desired_temp(pre.desired_temp)
  && oi_global_write_frame(pre, post)
}

// -- Isolette_System_Instance.thermostat.thermostat --

pub uninterp spec fn therm_action_heat_control(currentSetPoints: Isolette_Data_Model::Set_Points, lastCmd: Isolette_Data_Model::On_Off, current_temp: Isolette_Data_Model::Temp, temp_changed: Option<u8>, desired_temp: Option<Isolette_Data_Model::Set_Points>, heat_control: Option<Isolette_Data_Model::On_Off>) -> Option<Isolette_Data_Model::On_Off>;
pub uninterp spec fn therm_action_currentSetPoints(currentSetPoints: Isolette_Data_Model::Set_Points, lastCmd: Isolette_Data_Model::On_Off, current_temp: Isolette_Data_Model::Temp, temp_changed: Option<u8>, desired_temp: Option<Isolette_Data_Model::Set_Points>, heat_control: Option<Isolette_Data_Model::On_Off>) -> Isolette_Data_Model::Set_Points;
pub uninterp spec fn therm_action_lastCmd(currentSetPoints: Isolette_Data_Model::Set_Points, lastCmd: Isolette_Data_Model::On_Off, current_temp: Isolette_Data_Model::Temp, temp_changed: Option<u8>, desired_temp: Option<Isolette_Data_Model::Set_Points>, heat_control: Option<Isolette_Data_Model::On_Off>) -> Isolette_Data_Model::On_Off;

/** "THERM fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn therm_fire(pre: SystemState, post: SystemState) -> bool
{
  post.heatCmd == therm_action_heat_control(pre.setPoints, pre.lastCmd, pre.sensedTemp, pre.tempChanged, pre.desired_temp, pre.heatCmd)
  && post.setPoints == therm_action_currentSetPoints(pre.setPoints, pre.lastCmd, pre.sensedTemp, pre.tempChanged, pre.desired_temp, pre.heatCmd)
  && post.lastCmd == therm_action_lastCmd(pre.setPoints, pre.lastCmd, pre.sensedTemp, pre.tempChanged, pre.desired_temp, pre.heatCmd)
  && therm_global_write_frame(pre, post)
}

// -- Isolette_System_Instance.heat_source.heat_source --

pub uninterp spec fn hs_action_heater_state(heater_state: Isolette_Data_Model::On_Off, heat_control: Option<Isolette_Data_Model::On_Off>) -> Isolette_Data_Model::On_Off;

/** "HS fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn hs_fire(pre: SystemState, post: SystemState) -> bool
{
  post.heaterState == hs_action_heater_state(pre.heaterState, pre.heatCmd)
  && hs_global_write_frame(pre, post)
}

} // verus!
